import{_ as e,c as s,o as r,ag as o}from"./chunks/framework.Ci10AEOF.js";const n="/docs-website/assets/source_channel_reader.DGJIvjoK.png",a="/docs-website/assets/source_database_reader.CSX6XD-P.png",d="/docs-website/assets/source_dicom_listener.3v1NWZye.png",i="/docs-website/assets/source_file_reader.CVpyCIjg.png",c="/docs-website/assets/source_http_listener.B_iVk1XB.png",h="/docs-website/assets/source_javascript_reader.DGSE3vT1.png",l="/docs-website/assets/source_jms_listener.fU2s4Hid.png",g="/docs-website/assets/source_tcp_listener.CUmJXuMk.png",p="/docs-website/assets/source_web_service_listener.2eCl971b.png",k=JSON.parse('{"title":"Source Connectors","description":"Every source connector and the settings it exposes","frontmatter":{"title":"Source Connectors","description":"Every source connector and the settings it exposes"},"headers":[],"relativePath":"engine/connector_reference_sources.md","filePath":"engine/connector_reference_sources.md","lastUpdated":1793057853000}'),u={name:"engine/connector_reference_sources.md"};function m(b,t,f,y,v,S){return r(),s("div",null,t[0]||(t[0]=[o('<h1 id="source-connectors" tabindex="-1">Source connectors <a class="header-anchor" href="#source-connectors" aria-label="Permalink to &quot;Source connectors&quot;">​</a></h1><p>A channel has exactly one source connector. Nine types ship with the engine.</p><table tabindex="0"><thead><tr><th>Connector</th><th>Gets data by</th></tr></thead><tbody><tr><td><a href="#channel-reader">Channel Reader</a></td><td>Receiving from other channels on the same engine</td></tr><tr><td><a href="#database-reader">Database Reader</a></td><td>Polling a JDBC database</td></tr><tr><td><a href="#dicom-listener">DICOM Listener</a></td><td>Accepting DICOM associations</td></tr><tr><td><a href="#file-reader">File Reader</a></td><td>Polling a local directory, FTP, SFTP, S3, SMB, or WebDAV</td></tr><tr><td><a href="#http-listener">HTTP Listener</a></td><td>Serving HTTP requests</td></tr><tr><td><a href="#javascript-reader">JavaScript Reader</a></td><td>Running a script on a schedule</td></tr><tr><td><a href="#jms-listener">JMS Listener</a></td><td>Consuming from a JMS queue or topic</td></tr><tr><td><a href="#tcp-listener">TCP Listener</a></td><td>Accepting TCP connections, MLLP included</td></tr><tr><td><a href="#web-service-listener">Web Service Listener</a></td><td>Serving SOAP requests</td></tr></tbody></table><h2 id="settings-outside-the-connector-s-own-fields" tabindex="-1">Settings outside the connector&#39;s own fields <a class="header-anchor" href="#settings-outside-the-connector-s-own-fields" aria-label="Permalink to &quot;Settings outside the connector&#39;s own fields&quot;">​</a></h2><p>Three blocks sit above the connector&#39;s own configuration, and the type decides which of them you get.</p><p><strong>Listener settings</strong>, on the four listeners: TCP Listener, HTTP Listener, Web Service Listener, and DICOM Listener.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Local Address</strong></td><td><strong>All interfaces</strong> (the default) binds <code>0.0.0.0</code>. <strong>Specific interface</strong> binds the address you enter</td></tr><tr><td><strong>Local Port</strong></td><td>Port to bind. Defaults differ per connector and are given below. The <strong>Ports in Use</strong> button lists the listener ports the engine is already using</td></tr></tbody></table><p><strong>Polling settings</strong>, on the three that poll rather than listen: Database Reader, File Reader, and JavaScript Reader. They poll on an interval, at a set time, or on a cron schedule. See <a href="./polling_settings.html">Polling Settings</a>.</p><p><strong>Source settings</strong>, the only block all nine have: the source queue, the response selector, batch processing where the type supports it, and max processing threads. See <a href="./architecture_overview.html#connectors">Architecture</a>.</p><h2 id="channel-reader" tabindex="-1">Channel Reader <a class="header-anchor" href="#channel-reader" aria-label="Permalink to &quot;Channel Reader&quot;">​</a></h2><p>Receives messages from Channel Writer destinations on other channels, and from <code>router</code> calls in scripts. It has no fields of its own, and the Administrator shows <strong>No configurable settings.</strong> in their place. The source settings block above still applies, and what arrives is decided entirely by the sending side.</p><p><img src="'+n+'" alt="The Channel Reader settings on the channel editor&#39;s Source tab"></p><h2 id="database-reader" tabindex="-1">Database Reader <a class="header-anchor" href="#database-reader" aria-label="Permalink to &quot;Database Reader&quot;">​</a></h2><p>Polls a database for a result set. Whether that set becomes one message or one message per row is decided by <strong>Aggregate Results</strong> below. Write the query in SQL or build it in JavaScript.</p><p><img src="'+a+`" alt="The Database Reader settings on the channel editor&#39;s Source tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Driver</strong></td><td>Please Select One</td><td>JDBC driver. Required, JavaScript mode included. See <a href="#jdbc-drivers-and-url-templates">drivers and URL templates</a></td></tr><tr><td><strong>URL</strong></td><td></td><td>JDBC connection URL</td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td></td><td>Database credentials</td></tr><tr><td><strong>Use JavaScript</strong></td><td>No</td><td>Build the query in JavaScript instead of SQL. Switches the <strong>SQL</strong> field below to <strong>JavaScript</strong></td></tr><tr><td><strong>Keep Connection Open</strong></td><td>Yes</td><td>Reuse the connection between polls rather than reconnecting. Unavailable in JavaScript mode</td></tr><tr><td><strong>Aggregate Results</strong></td><td>No</td><td>Yes turns the whole result set into one message, sets <strong>Cache Results</strong> to Yes, and greys it out. No turns each row into its own message</td></tr><tr><td><strong>Cache Results</strong></td><td>Yes</td><td>Hold the whole result set in memory before processing. No streams from the cursor instead, and is what enables <strong>Fetch Size</strong>. Unavailable in JavaScript mode</td></tr><tr><td><strong>Fetch Size</strong></td><td>1000</td><td>JDBC ResultSet fetch size used when reading from the current cursor position. <strong>Applies only when Cache Results is No</strong>, and is greyed out otherwise, so at the default settings it does nothing</td></tr><tr><td><strong># of Retries on Error</strong></td><td>3</td><td>Attempts after a failed poll before giving up</td></tr><tr><td><strong>Retry Interval (ms)</strong></td><td>10000</td><td>Wait between those attempts</td></tr><tr><td><strong>Encoding</strong></td><td>Default</td><td>Character set used to convert binary column values (byte arrays and blobs) to text. Text columns are not affected</td></tr><tr><td><strong>SQL</strong> / <strong>JavaScript</strong></td><td></td><td>The select. The <strong>Generate</strong> buttons above it build a starting statement, or in JavaScript mode a connection block, from the settings above. In SQL mode each <code>\${}</code> is bound as a parameter rather than pasted in as text; see <a href="./velocity_variable_replacement.html#where-velocity-is-used">Where Velocity is used</a></td></tr><tr><td><strong>Run Post-Process SQL</strong> / <strong>Run Post-Process Script</strong></td><td>Never</td><td>Never, After each message, or Once after all messages. Runs a second statement after the message has been processed. With <strong>Aggregate Results</strong> Yes the options read For each row and Once for all rows. In JavaScript mode, After each message and For each row give the script a <code>resultMap</code> variable holding the row. Once for all rows gives it a <code>results</code> variable holding a list of maps, one per row, when the select script returned a ResultSet; when the script returned a List, the post-process does not run. Once after all messages, with <strong>Aggregate Results</strong> No, runs after each poll with neither variable</td></tr></tbody></table><p>The select runs again on every poll, so unless something changes the data it reads or the query itself, the same rows come back.</p><p><strong>JavaScript mode</strong></p><p>Choosing <strong>Use JavaScript</strong> disables three of the settings above: Keep Connection Open, Cache Results, and Fetch Size. The connector opens no database connection at all in this mode. The script opens its own, and has to return either a <code>ResultSet</code> or a <code>List&lt;Map&lt;String, Object&gt;&gt;</code>. A poll returning anything else fails. <strong>Aggregate Results</strong> applies only when the script returns a <code>ResultSet</code>; a returned <code>List</code> produces one message per map.</p><p>The four settings at the top of the connector still matter in this mode. <strong>Driver</strong> is required whether or not you use a script: the Administrator refuses to save the channel while it reads <em>Please Select One</em>, and there is no blank option. <strong>URL</strong> is validated only when Use JavaScript is No, and Username and Password are never validated. All four feed the generators. <strong>Generate: Connection</strong>, enabled only in this mode, pastes their current values, the password in plain text among them, into a connection block at the top of the script.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dbConn;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dbConn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DatabaseConnectionFactory.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createDatabaseConnection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;driver&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;url&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;username&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;password&gt;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // You may access this result below with $(&#39;column_name&#39;)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">finally</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (dbConn) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        dbConn.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">close</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The block is not runnable as generated. <code>result</code> is never assigned, so returning it fails the poll until you add the query yourself. <strong>Generate: Select</strong> is what adds it: it opens a live connection using those same four settings, which makes it the one place they are checked before a deploy, and inserts a <code>dbConn.executeCachedQuery(...)</code> line at the caret for the table you pick. The Post-Process JavaScript field has its own pair of buttons that do the same with <code>executeUpdate</code>.</p><p>Once generated, the driver, URL and credentials are string literals in the script. Editing the fields afterwards does not change them, and the connector&#39;s own copies are never read at runtime.</p><p>Clicking the <strong>Use JavaScript</strong> radio rewrites both script fields: Yes replaces their contents with the generated block, No empties them. Reopening a saved channel does not, so this happens only while editing.</p><h2 id="dicom-listener" tabindex="-1">DICOM Listener <a class="header-anchor" href="#dicom-listener" aria-label="Permalink to &quot;DICOM Listener&quot;">​</a></h2><p>Accepts DICOM associations and stores received objects as messages. Default port <strong>104</strong>.</p><p><img src="`+d+'" alt="The DICOM Listener settings on the channel editor&#39;s Source tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Application Entity</strong></td><td></td><td>AE title this listener answers to. Blank accepts any</td></tr><tr><td><strong>Store Received Objects in Directory</strong></td><td></td><td>Has no effect. A received object becomes a message, and nothing is written to this directory</td></tr><tr><td><strong>Max Async operations</strong></td><td>0</td><td>Maximum outstanding asynchronous operations. 0 leaves the DICOM library&#39;s default, which the field&#39;s tooltip gives as unlimited</td></tr><tr><td><strong>Pack PDV</strong></td><td>No</td><td>Pack the command and data PDVs into a single P-DATA-TF PDU</td></tr><tr><td><strong>Only Accept Default Transfer Syntax</strong></td><td>No</td><td>Refuse anything but implicit VR little endian</td></tr><tr><td><strong>Only Uncompressed Pixel Data</strong></td><td>No</td><td>Refuse compressed transfer syntaxes</td></tr><tr><td><strong>Accept Explict VR Big Endian</strong></td><td>No</td><td>Yes does not enable big endian: it limits the listener to the implicit VR little endian transfer syntax, as described below. The label carries the engine&#39;s own spelling</td></tr><tr><td><strong>TCP Delay</strong></td><td>Yes</td><td>Leave Nagle&#39;s algorithm on. No sets <code>TCP_NODELAY</code></td></tr></tbody></table><p>The three transfer syntax options above reset each other: Yes on <strong>Only Accept Default Transfer Syntax</strong> greys out the other two and sets them to No, and Yes on <strong>Only Uncompressed Pixel Data</strong> or <strong>Accept Explict VR Big Endian</strong> greys out <strong>Only Accept Default Transfer Syntax</strong>. In this build any Yes limits the listener to the implicit VR little endian transfer syntax. With all three at No, the listener keeps its default set of transfer syntaxes.</p><p><strong>Timing</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>DIMSE-RQ timeout (ms)</strong></td><td>60</td><td>Wait for a DIMSE request. Despite the ms label, the default 60 means 60 seconds, and any other value is read as milliseconds</td></tr><tr><td><strong>DIMSE-RSP delay (ms)</strong></td><td>0</td><td>Artificial delay before responding</td></tr><tr><td><strong>DIMSE-RSP interval period (s)</strong></td><td>10</td><td>Interval for the association reaper. Despite the s label, the default 10 means 10 seconds, and any other value is read as milliseconds</td></tr><tr><td><strong>ASSOCIATE-RQ timeout (ms)</strong></td><td>5</td><td>Wait for an association request. Despite the ms label, the default 5 means 5 seconds, and any other value is read as milliseconds</td></tr><tr><td><strong>A-RELEASE-RP timeout (s)</strong></td><td>5</td><td>Has no effect in 4.7.0. The value is stored and passed to the DICOM library, but nothing reads it, so the listener does not stop waiting for a release response</td></tr><tr><td><strong>Socket Close Delay After A-ABORT (ms)</strong></td><td>50</td><td>Delay before closing the socket after an abort</td></tr></tbody></table><p><strong>Buffers</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>P-DATA-TF PDUs max length sent (KB)</strong></td><td>16</td><td>Maximum PDU length sent</td></tr><tr><td><strong>P-DATA-TF PDUs max length received (KB)</strong></td><td>16</td><td>Maximum PDU length accepted</td></tr><tr><td><strong>Send Socket Buffer Size (KB)</strong></td><td>0</td><td>0 leaves the OS default</td></tr><tr><td><strong>Receive Socket Buffer Size (KB)</strong></td><td>0</td><td>0 leaves the OS default</td></tr><tr><td><strong>Transcoder Buffer Size (KB)</strong></td><td>1</td><td>Minimum buffer used to write a received object to file</td></tr></tbody></table><p><strong>TLS</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>TLS</strong></td><td>No TLS</td><td>No TLS, 3DES, AES, or Without</td></tr><tr><td><strong>Client Authentication TLS</strong></td><td>Yes</td><td>Require a client certificate</td></tr><tr><td><strong>Accept ssl v2 TLS handshake</strong></td><td>Yes</td><td>Yes, the default, removes the SSLv2Hello handshake from the listener&#39;s protocols, so the label reads opposite to its effect</td></tr><tr><td><strong>Keystore</strong> / <strong>Keystore Password</strong> / <strong>Key Password</strong></td><td></td><td>Identity presented by the listener</td></tr><tr><td><strong>Trust Store</strong> / <strong>Trust Store Password</strong></td><td></td><td>Certificates the listener will trust</td></tr></tbody></table><p>With <strong>TLS</strong> set to No TLS, the client authentication, SSLv2 handshake, keystore and trust store fields are greyed out. With TLS on, fill in <strong>Keystore</strong> and <strong>Trust Store</strong>: left blank, the listener falls back to the DICOM library&#39;s sample paths, <code>resource:tls/test_sys_2.p12</code> and <code>resource:tls/mesa_certs.jks</code>, which the 4.7.0 release does not ship.</p><div class="danger custom-block"><p class="custom-block-title">Broken in 4.7.0 on Java 17 and 21</p><p>With the JDK&#39;s default security settings, DICOM over TLS does not connect: with <strong>TLS</strong> set to 3DES, AES or Without, the handshake fails with <code>No appropriate protocol (protocol is disabled or cipher suites are inappropriate)</code>. No TLS works. Reported in <a href="https://github.com/OpenIntegrationEngine/engine/issues/556" target="_blank" rel="noreferrer">engine issue #556</a>; no fix has been proposed yet.</p></div><h2 id="file-reader" tabindex="-1">File Reader <a class="header-anchor" href="#file-reader" aria-label="Permalink to &quot;File Reader&quot;">​</a></h2><p>Polls a location and turns files into messages.</p><p><img src="'+i+'" alt="The File Reader settings on the channel editor&#39;s Source tab"></p><p><strong>Method</strong> is the first field on the panel. It decides how the location is addressed, whether credentials apply, and which connection settings are available.</p><table tabindex="0"><thead><tr><th>Method</th><th>Location fields</th><th>Credentials</th><th>Connection settings enabled</th></tr></thead><tbody><tr><td><strong>file</strong></td><td><strong>Directory</strong></td><td>none</td><td>none</td></tr><tr><td><strong>ftp</strong></td><td><code>ftp://</code> host, path</td><td>Anonymous, or username and password</td><td>Timeout, Passive Mode, Validate Connection, Advanced Options</td></tr><tr><td><strong>sftp</strong></td><td><code>sftp://</code> host, path</td><td>no Anonymous option; the fields stay editable</td><td>Timeout, Advanced Options</td></tr><tr><td><strong>smb</strong></td><td><code>smb://</code> host, path</td><td>no Anonymous option; the fields stay editable</td><td>Timeout, Advanced Options</td></tr><tr><td><strong>webdav</strong></td><td><code>http://</code> or <code>https://</code> host, path</td><td>Anonymous, or username and password</td><td>Secure Mode</td></tr><tr><td><strong>Amazon S3</strong></td><td><strong>S3 Bucket</strong>, path</td><td>Anonymous, or AWS Access Key ID and Secret Access Key</td><td>Timeout, Advanced Options</td></tr></tbody></table><p>Timeout must not be left blank for FTP, SFTP, or SMB. <code>file</code> is the only method with a single <strong>Directory</strong> field; the others split the location into a host and a path, with the protocol prefix as the host&#39;s label. Secure Mode is what switches WebDAV between <code>http://</code> and <code>https://</code>. An installed extension that adds TLS to the File Reader changes the FTP prefix to <code>ftps://</code>. Under S3 the credential fields are relabelled <strong>AWS Access Key ID</strong> and <strong>AWS Secret Access Key</strong>, and the move-to fields become <strong>Move-to S3 Bucket / Directory</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Broken in 4.7.0</p><p>A File Reader set to <strong>webdav</strong> fails to start, and the server log shows <code>NoClassDefFoundError: org/jdom/input/DOMBuilder</code>. Fix proposed in <a href="https://github.com/OpenIntegrationEngine/engine/pull/546" target="_blank" rel="noreferrer">engine PR #546</a>, not yet in a release.</p></div><p>On Windows, <strong>Directory</strong> under <code>file</code> can be a UNC path such as <code>\\\\server\\share\\inbound</code>. The Administrator stores it with forward slashes, <code>//server/share/inbound</code>, which Windows still reads as the same share. The account the OIE service runs as needs access to the share. On Linux, mount the share, in <code>/etc/fstab</code> or with an automounter, and point the <code>file</code> method at the mount point.</p><p>The remaining settings, in the order they appear:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Filename Filter Pattern</strong></td><td><code>*</code></td><td>Wildcard by default; the <strong>Regular Expression</strong> checkbox switches it to a regex</td></tr><tr><td><strong>Include All Subdirectories</strong></td><td>No</td><td>Recurse</td></tr><tr><td><strong>Ignore . files</strong></td><td>Yes</td><td>Skip dotfiles</td></tr><tr><td><strong>Anonymous</strong></td><td>Yes</td><td>Offered by FTP, WebDAV, and S3 only. Choosing Yes disables the two fields below and refills them with <code>anonymous</code>, except under S3, which clears them</td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td><code>anonymous</code> / <code>anonymous</code></td><td>Both fields carry <code>anonymous</code> by default, so SFTP and SMB, which have no Anonymous option, open with it already filled in and editable. S3 starts them empty. A username is required whenever Anonymous is off, and a password is too, unless the method is SFTP and the Advanced Options use a key file. Neither is required under S3 when Use Default Credential Provider Chain is checked</td></tr><tr><td><strong>Timeout (ms)</strong></td><td>10000</td><td>How long to wait when connecting. Not available for <code>file</code> or WebDAV</td></tr><tr><td><strong>Secure Mode</strong></td><td>Yes</td><td>WebDAV over HTTPS. WebDAV only</td></tr><tr><td><strong>Passive Mode</strong></td><td>Yes</td><td>FTP passive transfers. FTP only</td></tr><tr><td><strong>Validate Connection</strong></td><td>Yes</td><td>Test the connection before each operation. FTP only</td></tr><tr><td><strong>After Processing Action</strong></td><td>None</td><td>None, Move, or Delete. None leaves the file in place, so the next poll reads it again</td></tr><tr><td><strong>Move-to Directory</strong> / <strong>Move-to File Name</strong></td><td></td><td>Where a moved file goes. The directory is on the server the file was read from, so under <strong>sftp</strong> it is on the SFTP server and cannot be a directory on the OIE server. Enabled only when <strong>After Processing Action</strong> is Move. A blank directory leaves the file where it is, a blank file name keeps the original one, and an existing file at the destination is deleted first</td></tr><tr><td><strong>Error Reading Action</strong></td><td>None</td><td>None, Move, or Delete, for a file that could not be read. A message that errors inside the channel, for example in the preprocessor, does not count, and its file is handled as for any other message</td></tr><tr><td><strong>Error in Response Action</strong></td><td>After Processing Action</td><td>After Processing Action, Move, or Delete, for a file whose message got an error response. Not applied when batch processing is on</td></tr><tr><td><strong>Error Move-to Directory</strong> / <strong>Error Move-to File Name</strong></td><td></td><td>Destination for either error action, on the same server, under the same rules. Enabled when either error action is Move</td></tr><tr><td><strong>Check File Age</strong></td><td>Yes</td><td>Skip files younger than <strong>File Age</strong></td></tr><tr><td><strong>File Age (ms)</strong></td><td>1000</td><td>Minimum age before a file is read. Greyed out when <strong>Check File Age</strong> is No. Under <strong>ftp</strong> the engine takes the file time from the server&#39;s directory listing; a listing that gives times only to the minute, as vsftpd&#39;s does, lets a file be read up to a minute early</td></tr><tr><td><strong>File Size (bytes)</strong></td><td>0, no maximum</td><td>Minimum and maximum a file must fall between. <strong>Ignore Maximum</strong> leaves the upper bound open, and is checked by default</td></tr><tr><td><strong>Sort Files By</strong></td><td>Date</td><td>Date, Name, or Size. Decides the order files are processed in</td></tr><tr><td><strong>File Type</strong></td><td>Text</td><td>Text or Binary. Binary base64 encodes the content</td></tr><tr><td><strong>Encoding</strong></td><td>Default</td><td>Character set, Text only</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">A move happens on the server the file was read from</p><p>A move runs over the same connection the file was read from. Under <strong>sftp</strong> the move-to directory is a directory on the SFTP server, under <strong>ftp</strong> on the FTP server, and under <strong>smb</strong> a path on the same SMB server. It cannot be a directory on the OIE server, and nothing is copied back to the OIE server on the way. Only the <strong>file</strong> method moves files on the OIE server&#39;s own disk, because that is where it reads from. The same goes for <strong>Error Move-to Directory</strong>, and for the Delete actions, which delete on the remote side.</p><p>Relative paths resolve differently per method. FTP and SFTP change to the read directory first, so a path with no leading <code>/</code> is taken relative to the directory being read, and a leading <code>/</code> is absolute on the remote host. SMB resolves it against the server, so the first part of a relative path is the share name, for example <code>share/archive</code>. Under <code>file</code> a relative path resolves against the engine&#39;s working directory, not the directory being read, so use an absolute path. WebDAV paths always start from the server root. S3 reads the field as a bucket and a prefix, which is why it is labelled <strong>Move-to S3 Bucket / Directory</strong> and why a move can cross buckets. Backslashes typed into either move-to directory field are converted to forward slashes when the channel is saved. A move-to directory that does not exist is created.</p></div><p>The wrench button beside <strong>Method</strong> opens a per-protocol dialog, and the <strong>Advanced Options</strong> row below it shows a read-only summary of what is set. See <a href="#file-protocol-advanced-settings">file protocol advanced settings</a>.</p><h2 id="http-listener" tabindex="-1">HTTP Listener <a class="header-anchor" href="#http-listener" aria-label="Permalink to &quot;HTTP Listener&quot;">​</a></h2><p>Serves HTTP requests. Default port <strong>80</strong>, and the <strong>HTTP URL</strong> shown on the panel is built from the address of the server the Administrator is connected to, the Local Port, and the Base Context Path.</p><p><img src="'+c+'" alt="The HTTP Listener settings on the channel editor&#39;s Source tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Base Context Path</strong></td><td></td><td>Path this connector answers on. Blank means the root, not nothing. See below</td></tr><tr><td><strong>Receive Timeout (ms)</strong></td><td>30000</td><td>Maximum idle time for a connection</td></tr><tr><td><strong>Request Header Size (bytes)</strong></td><td>8192</td><td>Maximum combined size of all request headers. Larger requests are rejected with 431 Request Header Fields Too Large before the channel sees them. Template substitutions are allowed, and the value must resolve to a positive whole number, or the connector fails to start</td></tr><tr><td><strong>Message Content</strong></td><td>Plain Body</td><td>Plain Body passes the body through. XML Body wraps the body in XML, and with <strong>Include Metadata</strong> set to Yes it also adds the remote address, request URL, method, path, context path, parameters, and headers</td></tr><tr><td><strong>Parse Multipart</strong></td><td>Yes</td><td>Split a multipart request into parts. XML Body only</td></tr><tr><td><strong>Include Metadata</strong></td><td>No</td><td>Include method, context path, headers, and query parameters. XML Body only</td></tr><tr><td><strong>Binary MIME Types</strong></td><td><code>application/.*(?&lt;!json|xml)$|image/.*|video/.*|audio/.*</code></td><td>Content types treated as binary and base64 encoded. <strong>Regular Expression</strong> switches it between a regex and a plain list</td></tr><tr><td><strong>Response Content Type</strong></td><td>text/plain</td><td>Value of the response&#39;s Content-Type header</td></tr><tr><td><strong>Response Data Type</strong></td><td>Text</td><td>Text or Binary. Binary base64 decodes the response before sending</td></tr><tr><td><strong>Charset Encoding</strong></td><td>UTF-8</td><td>Character set. Disabled when <strong>Response Data Type</strong> is Binary</td></tr><tr><td><strong>Response Status Code</strong></td><td></td><td>HTTP status to return. Blank returns 200, or 500 when the selected response has status ERROR</td></tr><tr><td><strong>Response Headers</strong></td><td></td><td>Headers to return. <strong>Use Map</strong> takes them from a map variable instead of the table</td></tr><tr><td><strong>Static Resources</strong></td><td></td><td>Paths served directly by the connector, each with its own content type and value, without producing a message</td></tr></tbody></table><p>The engine normalizes <strong>Base Context Path</strong>: a leading slash is added if you left it off, and a trailing slash is stripped, so <code>orders</code>, <code>/orders</code>, and <code>/orders/</code> all give the same context, and blank and <code>/</code> are the same thing. A listener answers its context path with the trailing slash, such as <code>/orders/</code>, and everything below it. A request to <code>/orders</code> without the slash gets a 302 redirect to <code>/orders/</code>, and a POST to <code>/orders</code> is not delivered to the channel, so send to <code>/orders/</code>. At the root it answers every request that reaches its port.</p><p>Each HTTP Listener builds its own server bound to its own host and port, so two channels cannot share a port and divide it by context path. Static resource paths are appended to the base.</p><p>Authentication is a separate plugin; see <a href="#http-authentication">HTTP authentication</a>.</p><h2 id="javascript-reader" tabindex="-1">JavaScript Reader <a class="header-anchor" href="#javascript-reader" aria-label="Permalink to &quot;JavaScript Reader&quot;">​</a></h2><p>Runs a script on the polling schedule. The script&#39;s return value becomes the message, a returned Java <code>List</code> produces one message per element, and returning nothing produces no message.</p><p><img src="'+h+'" alt="The JavaScript Reader settings on the channel editor&#39;s Source tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>JavaScript</strong></td><td>The script to run</td></tr></tbody></table><p>This connector&#39;s scope is narrower than most: it has no <code>channelMap</code>, <code>connectorMap</code>, <code>sourceMap</code>, <code>responseMap</code>, or <code>connectorMessage</code>, because the script runs before any message exists. The JavaScript Writer does have them. See <a href="./script_scope_and_user_api.html">Script Scope and User API</a>.</p><h2 id="jms-listener" tabindex="-1">JMS Listener <a class="header-anchor" href="#jms-listener" aria-label="Permalink to &quot;JMS Listener&quot;">​</a></h2><p>Consumes from a JMS queue or topic.</p><p><img src="'+l+'" alt="The JMS Listener settings on the channel editor&#39;s Source tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Use JNDI</strong></td><td></td><td>Off names a factory class, on names a JNDI lookup</td></tr><tr><td><strong>Provider URL</strong> / <strong>Initial Context Factory</strong></td><td></td><td>JNDI context, JNDI on</td></tr><tr><td><strong>Connection Factory Name</strong></td><td></td><td>JNDI lookup name, JNDI on. Not a class name</td></tr><tr><td><strong>Connection Factory Class</strong></td><td></td><td>Vendor <code>ConnectionFactory</code> implementation, JNDI off</td></tr><tr><td><strong>Connection Properties</strong></td><td></td><td>Additional properties passed to the factory</td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td></td><td>Broker credentials</td></tr><tr><td><strong>Destination Type</strong></td><td>Queue</td><td>Queue or Topic</td></tr><tr><td><strong>Durable</strong></td><td>No</td><td>Durable topic subscription. Available only when <strong>Destination Type</strong> is Topic, and needs a <strong>Client ID</strong></td></tr><tr><td><strong>Destination Name</strong></td><td></td><td>Queue or topic to consume from</td></tr><tr><td><strong>Client ID</strong></td><td></td><td>JMS client identifier, set on the connection. A durable Topic subscription needs one, with <strong>Use JNDI</strong> on or off. The Administrator checks for it only when <strong>Use JNDI</strong> is off</td></tr><tr><td><strong>Reconnect Interval (ms)</strong></td><td>10000</td><td>Wait before reconnecting after a broker failure</td></tr><tr><td><strong>Selector</strong></td><td></td><td>JMS message selector expression, filtering at the broker</td></tr></tbody></table><p>The provider&#39;s client jars go in a library resource (<strong>Settings</strong> &gt; <strong>Resources</strong>). In the channel&#39;s <strong>Set Dependencies</strong> &gt; <strong>Library Resources</strong>, select that resource on the <strong>Source Connector</strong> entry. Selecting it only on the <strong>Channel</strong> entry is not enough: the listener fails to start with <code>Failed to instantiate ConnectionFactory class</code>.</p><h2 id="tcp-listener" tabindex="-1">TCP Listener <a class="header-anchor" href="#tcp-listener" aria-label="Permalink to &quot;TCP Listener&quot;">​</a></h2><p>Accepts TCP connections. Default port <strong>6661</strong>.</p><p><img src="'+g+'" alt="The TCP Listener settings on the channel editor&#39;s Source tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Transmission Mode</strong></td><td>MLLP</td><td>MLLP or Basic TCP. <strong>Sample Frame</strong> previews the framing bytes. See <a href="#transmission-modes">transmission modes</a></td></tr><tr><td><strong>Mode</strong></td><td>Server</td><td>Server binds and accepts, and is the only mode with <strong>Max Connections</strong>. Client connects out, and is the only mode with <strong>Remote Address</strong>, <strong>Remote Port</strong>, <strong>Override Local Binding</strong>, and <strong>Reconnect Interval</strong></td></tr><tr><td><strong>Remote Address</strong> / <strong>Remote Port</strong></td><td></td><td>Where to connect, Client mode only</td></tr><tr><td><strong>Override Local Binding</strong></td><td>No</td><td>Bind a specific local address and port for the outbound connection. Client mode only</td></tr><tr><td><strong>Reconnect Interval (ms)</strong></td><td>5000</td><td>Wait before reconnecting, Client mode</td></tr><tr><td><strong>Max Connections</strong></td><td>10</td><td>Concurrent connections accepted. Server mode only</td></tr><tr><td><strong>Receive Timeout (ms)</strong></td><td>0</td><td>Idle timeout on a connection. It closes the connection only when <strong>Keep Connection Open</strong> is No; with Yes the connection stays open after the timeout. 0 waits indefinitely</td></tr><tr><td><strong>Buffer Size (bytes)</strong></td><td>65536</td><td>Applied to both the socket receive buffer and the socket send buffer, and to the buffered output stream of the response</td></tr><tr><td><strong>Keep Connection Open</strong></td><td>Yes</td><td>Hold the connection open between messages</td></tr><tr><td><strong>Data Type</strong></td><td>Text</td><td>Text or Binary. Binary base64 encodes the payload</td></tr><tr><td><strong>Encoding</strong></td><td>Default</td><td>Character set, Text only</td></tr><tr><td><strong>Respond on New Connection</strong></td><td>No</td><td>Yes, No, or Message Recovery. No sends the response back on the same connection</td></tr><tr><td><strong>Response Address</strong> / <strong>Response Port</strong></td><td></td><td>Where the response goes. Enabled when <strong>Respond on New Connection</strong> is Yes or Message Recovery</td></tr></tbody></table><h2 id="web-service-listener" tabindex="-1">Web Service Listener <a class="header-anchor" href="#web-service-listener" aria-label="Permalink to &quot;Web Service Listener&quot;">​</a></h2><p>Publishes a SOAP endpoint. Default port <strong>8081</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Broken in 4.7.0 on Java 19 and later</p><p>The listener answers every SOAP request with an HTTP 500, while its WSDL still loads. <a href="https://github.com/OpenIntegrationEngine/engine/issues/509" target="_blank" rel="noreferrer">Engine issue #509</a> reports this on Java 19 and later; a fix is proposed in <a href="https://github.com/OpenIntegrationEngine/engine/pull/508" target="_blank" rel="noreferrer">engine PR #508</a>, not yet in a release. Until then, run the engine on Java 17, or add the <code>-classpath/a</code> line from engine issue #509 to <code>conf/custom.vmoptions</code>.</p></div><p><img src="'+p+'" alt="The Web Service Listener settings on the channel editor&#39;s Source tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Web Service</strong></td><td>Default service</td><td><strong>Default service</strong> fills in the default class below and greys out <strong>Service Class Name</strong>. <strong>Custom service</strong> uses the class you name</td></tr><tr><td><strong>Service Class Name</strong></td><td><code>com.mirth.connect.connectors.ws.DefaultAcceptMessage</code></td><td>Class implementing the service. It must extend <code>com.mirth.connect.connectors.ws.AcceptMessage</code> directly and have a constructor that takes the Web Service Listener. If it does not, starting the connector logs an error and the default class is used instead. The default class publishes a single <code>acceptMessage(String)</code> operation</td></tr><tr><td><strong>Service Name</strong></td><td>Mirth</td><td>Last part of the endpoint path, <code>/services/&lt;Service Name&gt;</code>. With the default service, the WSDL names the service <code>DefaultAcceptMessageService</code> whatever this is set to</td></tr><tr><td><strong>Binding</strong></td><td>Default</td><td>Default, SOAP 1.1, or SOAP 1.2. Default publishes the service with the binding declared in the class, and SOAP 1.1 when it declares none</td></tr><tr><td><strong>WSDL URL</strong></td><td></td><td>Display only. Shows <code>http://&lt;server&gt;:&lt;port&gt;/services/&lt;Service Name&gt;?wsdl</code> straight away, without a deploy, and updates as you change the port or service name</td></tr><tr><td><strong>Method</strong></td><td><code>String acceptMessage(String message)</code></td><td>Display only. Shows the default operation signature, or <code>&lt;Custom Web Service Methods&gt;</code> under Custom service</td></tr></tbody></table><h2 id="shared-reference" tabindex="-1">Shared reference <a class="header-anchor" href="#shared-reference" aria-label="Permalink to &quot;Shared reference&quot;">​</a></h2><h3 id="transmission-modes" tabindex="-1">Transmission modes <a class="header-anchor" href="#transmission-modes" aria-label="Permalink to &quot;Transmission modes&quot;">​</a></h3><p>Used by both the TCP Listener and the <a href="./connector_reference_destinations.html#tcp-sender">TCP Sender</a>.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>MLLP</strong></td><td>HL7 framing: start byte <code>0x0B</code>, end bytes <code>0x1C 0x0D</code>. MLLPv2 adds configurable acknowledgement bytes</td></tr><tr><td><strong>Basic TCP</strong></td><td>Start and end bytes you choose</td></tr></tbody></table><h3 id="jdbc-drivers-and-url-templates" tabindex="-1">JDBC drivers and URL templates <a class="header-anchor" href="#jdbc-drivers-and-url-templates" aria-label="Permalink to &quot;JDBC drivers and URL templates&quot;">​</a></h3><p>Used by both the Database Reader and the <a href="./connector_reference_destinations.html#database-writer">Database Writer</a>. The list ships in <code>conf/dbdrivers.xml</code>. Once a driver list is saved from the Administrator, with the wrench button beside <strong>Driver</strong>, the engine uses the saved list and no longer reads the file.</p><table tabindex="0"><thead><tr><th>Driver</th><th>Class</th><th>URL Template</th></tr></thead><tbody><tr><td>MySQL</td><td><code>com.mysql.cj.jdbc.Driver</code></td><td><code>jdbc:mysql://host:port/dbname</code></td></tr><tr><td>Oracle</td><td><code>oracle.jdbc.driver.OracleDriver</code></td><td><code>jdbc:oracle:thin:@host:port:dbname</code></td></tr><tr><td>PostgreSQL</td><td><code>org.postgresql.Driver</code></td><td><code>jdbc:postgresql://host:port/dbname</code></td></tr><tr><td>SQL Server/Sybase (jTDS)</td><td><code>net.sourceforge.jtds.jdbc.Driver</code></td><td><code>jdbc:jtds:sqlserver://host:port/dbname</code></td></tr><tr><td>Microsoft SQL Server</td><td><code>com.microsoft.sqlserver.jdbc.SQLServerDriver</code></td><td><code>jdbc:sqlserver://host:port;databaseName=dbname</code></td></tr><tr><td>SQLite</td><td><code>org.sqlite.JDBC</code></td><td><code>jdbc:sqlite:dbfile.db</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These are the databases a channel can <em>read from and write to</em>. They are not the same set OIE supports for its own message repository. See <a href="./database_support.html">Database Support</a> for that. SQLite, for instance, is available to channels but is not a supported backing store for OIE itself.</p></div><h3 id="file-protocol-advanced-settings" tabindex="-1">File protocol advanced settings <a class="header-anchor" href="#file-protocol-advanced-settings" aria-label="Permalink to &quot;File protocol advanced settings&quot;">​</a></h3><p>Reached through the wrench button beside <strong>Method</strong> on the File Reader and the <a href="./connector_reference_destinations.html#file-writer">File Writer</a>. The dialog&#39;s contents depend on the selected method. Passive mode, secure mode, and the timeout are not in these dialogs; they are on the main connector panel. The S3 dialog has no bucket field, because the bucket is the <strong>S3 Bucket</strong> field on the main panel, and there is no domain field for SMB.</p><ul><li><strong>FTP</strong>: Initial Commands</li><li><strong>SFTP</strong>: Authentication, Public/Private Key File, Passphrase, Host Key Checking, Known Hosts File, and a free-form Configuration Options map</li><li><strong>S3</strong>: Use Default Credential Provider Chain, Use Temporary Credentials, Duration (seconds), Region, Custom HTTP Headers</li><li><strong>SMB</strong>: SMB Minimum Version, SMB Maximum Version</li></ul><p>For S3 the generic Username and Password fields are relabelled AWS Access Key ID and AWS Secret Access Key on the main panel.</p><h3 id="http-authentication" tabindex="-1">HTTP authentication <a class="header-anchor" href="#http-authentication" aria-label="Permalink to &quot;HTTP authentication&quot;">​</a></h3><p>HTTP authentication is a plugin that ships with the engine. It adds authentication to the HTTP Listener and the Web Service Listener, with these methods:</p><ul><li><strong>Basic Authentication</strong>: username and password</li><li><strong>Digest Authentication</strong>: digest challenge and response</li><li><strong>JavaScript</strong>: authentication logic you write</li><li><strong>Custom Java Class</strong>: authentication delegated to a class you supply</li><li><strong>OAuth 2.0 Token Verification</strong>: validates an incoming OAuth 2.0 token</li></ul>',90)]))}const T=e(u,[["render",m]]);export{k as __pageData,T as default};
